		require.NoError(t, os.MkdirAll(infoDir, 0o755))
		require.NoError(t, os.WriteFile(filepath.Join(infoDir, "alternates"), []byte(alternateDir+"\n"), 0o644))

		hasAlternates, err := hasObjectAlternates(worktreeDir)
