package gitrepo

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-billy/v6"
	"github.com/go-git/go-billy/v6/osfs"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing/cache"
	gitfilesystem "github.com/go-git/go-git/v6/storage/filesystem"
	"github.com/go-git/go-git/v6/storage/filesystem/dotgit"
)

const gitDir = ".git"

// sharedObjectCache is one process-wide object cache. go-git uses the cache
// passed to the storage as its delta-base cache, so a per-open cache makes
// every open re-read pack data from scratch.
var sharedObjectCache = cache.NewObjectLRUDefault()

// OpenCurrent opens the current git worktree with object alternates enabled.
// The caller owns the returned repository and must close it.
//
// A worktree root that will not resolve is an error, not a reason to open the
// current directory. This used to fall back to ".", which is a different
// repository whenever the two disagree, and go-git disagrees with git in exactly
// the cases that made the resolution fail:
//
//   - git exports GIT_DIR and GIT_WORK_TREE to the hooks it runs, and
//     paths.WorktreeRoot honours them. OpenPath(".") cannot see them, so a hook
//     running for repo A whose git lookup failed opened repo B, the unrelated
//     repository it happened to be sitting in. Verified.
//   - git refuses a repository whose ownership fails its safe.directory check,
//     and refuses a .git it cannot parse. go-git applies neither check, so the
//     fallback opened repositories the user's own git declines to touch.
//
// Five of the six callers write through the repository they are handed, and all
// five sit behind the root pre-run, which already refuses to run when the
// worktree root does not resolve — so this closes a trap rather than a live bug.
// The sixth is a best-effort advisory that genuinely wants the old behaviour and
// now asks for it by name: see OpenCurrentOrCwd.
func OpenCurrent(ctx context.Context) (*git.Repository, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve worktree root: %w", err)
	}
	return OpenPath(repoRoot)
}

// OpenCurrentOrCwd is OpenCurrent with the current directory as a fallback when
// the worktree root will not resolve.
//
// It exists for one caller, WarnCheckpointPolicyIfNeeded, and the properties
// that make it acceptable there do not generalise: it is dispatched from
// main.go after cobra has finished, so unlike every other repository open it has
// no pre-run guard in front of it; it only READS a policy ref to decide whether
// to print an advisory line; and it discards every error it gets. Opening the
// wrong repository there costs a warning that is skipped or shown, not a write
// that lands in the wrong place.
//
// Do not reach for this because OpenCurrent started returning an error. That
// error means Entire could not establish which repository this is, and for
// anything that writes, stopping is the whole point.
func OpenCurrentOrCwd(ctx context.Context) (*git.Repository, error) {
	if repo, err := OpenCurrent(ctx); err == nil {
		return repo, nil
	}
	return OpenPath(".")
}

// OpenPath opens a git repository with object alternates enabled.
// The caller owns the returned repository and must close it.
func OpenPath(repoRoot string) (*git.Repository, error) {
	repo, err := openPathWithAlternates(repoRoot)
	if err != nil {
		if hasAlternates, altErr := hasObjectAlternates(repoRoot); altErr == nil && hasAlternates {
			return nil, fmt.Errorf("failed to open repository with alternates support: %w", err)
		}

		// Intentional PlainOpen fallback for unusual layouts that do not use
		// alternates. Repositories with alternates must not silently downgrade
		// because PlainOpen cannot read absolute alternate object directories.
		if fallbackRepo, fallbackErr := git.PlainOpen(repoRoot); fallbackErr == nil {
			return fallbackRepo, nil
		}
		return nil, fmt.Errorf("failed to open repository: %w", err)
	}
	return repo, nil
}

// ResolveDotGitPath resolves the .git entry for a worktree without opening the
// repository. Callers that need Git metadata should use this shared resolver.
func ResolveDotGitPath(repoRoot string) (string, error) {
	return resolveDotGitPath(repoRoot)
}

// ResolveCommonGitPath resolves the shared Git directory for a resolved .git
// directory. An empty result means the repository has no commondir file.
func ResolveCommonGitPath(dotGitPath string) (string, error) {
	return resolveCommonGitPath(dotGitPath)
}

func hasObjectAlternates(repoRoot string) (bool, error) {
	repoRoot, err := filepath.Abs(repoRoot)
	if err != nil {
		return false, fmt.Errorf("resolve repository root: %w", err)
	}

	dotGitPath, err := resolveDotGitPath(repoRoot)
	if err != nil {
		return false, fmt.Errorf("resolve .git path: %w", err)
	}

	commonGitPath, err := resolveCommonGitPath(dotGitPath)
	if err != nil {
		return false, fmt.Errorf("resolve common git path: %w", err)
	}

	candidates := []string{filepath.Join(dotGitPath, "objects", "info", "alternates")}
	if commonGitPath != "" {
		candidates = append(candidates, filepath.Join(commonGitPath, "objects", "info", "alternates"))
	}
	for _, candidate := range candidates {
		if _, err := os.Stat(candidate); err == nil {
			return true, nil
		} else if !errors.Is(err, os.ErrNotExist) {
			return false, fmt.Errorf("stat alternates file: %w", err)
		}
	}
	return false, nil
}

func openPathWithAlternates(repoRoot string) (*git.Repository, error) {
	repoRoot, err := filepath.Abs(repoRoot)
	if err != nil {
		return nil, fmt.Errorf("resolve repository root: %w", err)
	}

	dotGitPath, err := resolveDotGitPath(repoRoot)
	if err != nil {
		return nil, err
	}

	commonGitPath, err := resolveCommonGitPath(dotGitPath)
	if err != nil {
		return nil, err
	}

	// Wrap the git-dir filesystems so relative alternate object directories are
	// rewritten to absolute paths on read; go-git cannot follow relative
	// alternates on its own. The alternates file lives under the common git dir
	// for linked worktrees, so wrap both.
	dotGitFS := wrapAlternatesRewrite(osfs.New(dotGitPath, osfs.WithBoundOS()))
	var commonGitFS billy.Filesystem
	if commonGitPath != "" {
		commonGitFS = wrapAlternatesRewrite(osfs.New(commonGitPath, osfs.WithBoundOS()))
	}

	repositoryFS := dotgit.NewRepositoryFilesystem(dotGitFS, commonGitFS)
	// Shared clones write absolute object directories to objects/info/alternates;
	// an OS-rooted filesystem lets go-git follow those paths outside .git.
	storage := gitfilesystem.NewStorageWithOptions(
		repositoryFS,
		sharedObjectCache,
		gitfilesystem.Options{
			AlternatesFS: newAlternatesFilesystem(),
		},
	)

	// go-git's filesystem storer cannot read the reftable ref backend: it reads
	// refs from .git/refs, packed-refs and .git/HEAD, none of which are
	// authoritative in a reftable repository, and its extension check rejects
	// extensions.refstorage=reftable outright. Route ref operations through the
	// git CLI for such repositories while keeping object storage on go-git.
	//
	// TODO: drop the reftable branch below and the whole reftableStorer
	// (reftable.go) once go-git ships a native reftable reader/writer. At that
	// point a plain git.Open(storage, worktreeFS) will handle reftable
	// repositories directly and this CLI-backed shim is dead weight.
	worktreeFS := osfs.New(repoRoot, osfs.WithBoundOS())
	if repoUsesReftable(dotGitPath, commonGitPath) {
		repo, err := git.Open(newReftableStorer(storage, dotGitPath), worktreeFS)
		if err != nil {
			_ = storage.Close()
			return nil, fmt.Errorf("open reftable repository storage: %w", err)
		}
		return repo, nil
	}

	repo, err := git.Open(storage, worktreeFS)
	if err != nil {
		_ = storage.Close()
		return nil, fmt.Errorf("open repository storage: %w", err)
	}
	return repo, nil
}

func resolveDotGitPath(repoRoot string) (string, error) {
	gitPath := filepath.Join(repoRoot, gitDir)
	info, err := os.Stat(gitPath)
	if err != nil {
		return "", fmt.Errorf("stat .git path: %w", err)
	}
	if info.IsDir() {
		return gitPath, nil
	}

	content, err := os.ReadFile(gitPath) //nolint:gosec // gitPath is resolved from the git worktree root.
	if err != nil {
		return "", fmt.Errorf("read .git file: %w", err)
	}

	line, _, _ := strings.Cut(string(content), "\n")
	gitdir, ok := strings.CutPrefix(strings.TrimSpace(line), "gitdir:")
	if !ok {
		return "", errors.New(".git file has no gitdir prefix")
	}

	gitdir = strings.TrimSpace(gitdir)
	if filepath.IsAbs(gitdir) {
		return filepath.Clean(gitdir), nil
	}
	return filepath.Clean(filepath.Join(repoRoot, gitdir)), nil
}

func resolveCommonGitPath(dotGitPath string) (string, error) {
	content, err := os.ReadFile(filepath.Join(dotGitPath, "commondir")) //nolint:gosec // dotGitPath is resolved from the git worktree root.
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("read commondir file: %w", err)
	}

	commonPath := strings.TrimSpace(string(content))
	if commonPath == "" {
		return "", nil
	}
	if filepath.IsAbs(commonPath) {
		return filepath.Clean(commonPath), nil
	}
	return filepath.Clean(filepath.Join(dotGitPath, commonPath)), nil
}
// Package gitdir owns access to the git common directory — .git in an ordinary
// checkout, and the main repository's .git when running from a linked worktree.
//
// Entire keeps a lot of state there, deliberately: session state, advisory
// locks, the checkpoint push queue, the redaction prefix cache, investigation
// runs, review manifests, and the captured checkpoint-sync election all live in
// the common dir rather than under .entire, because they are per-clone and must
// not be committed or walked into a checkpoint tree. That makes this directory
// the same kind of trust surface .entire is, and it gets the same treatment: one
// *os.Root per common dir, opened once and shared, with every read and write
// resolved as a name inside it.
//
// Two properties come from that, and neither survives a call site reverting to
// os.ReadFile on a joined path:
//
//   - Containment. Names here are built from agent-supplied session IDs and
//     investigation run IDs. Several call sites carry hand-written comments
//     explaining that an unvalidated ID would be a path-traversal sink feeding
//     os.RemoveAll. A root makes that structural instead of a precondition each
//     caller has to keep honouring.
//   - One directory handle per clone. The resolver shells out to git; before
//     this package, strategy.GetGitCommonDir did so on *every* call with no
//     cache at all, on hook paths.
//
// Unlike .entire there is no create/no-create split: the common dir is the
// repository, so it always exists by the time anything here is called. What
// needs creating are Entire's own subdirectories inside it, via
// osroot.MkdirAllNoSymlink.
package gitdir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

var (
	// resolveMu guards the resolved-path cache, which is keyed by the working
	// directory the answer was derived in (see CommonDir).
	resolveMu     sync.RWMutex
	cachedDir     string
	cachedFromCwd string
)

// CommonDir returns the absolute path of the git common directory, caching the
// result per working directory.
//
// Absolute is the load-bearing word. `git rev-parse --git-common-dir` answers
// relative to the process's directory — from a subdirectory it returns
// "../../../.git" — and the two implementations this replaced passed that
// straight through, so every path built on it was only valid while the process
// stayed put. Resolving it once here means a stored lock path or queue path
// still names the same file later, and it is what lets Open hold a handle
// rather than re-resolving a string.
func CommonDir(ctx context.Context) (string, error) {
	cwd, err := os.Getwd() //nolint:forbidigo // cache key, and the base the git answer is relative to
	if err != nil {
		cwd = ""
	}

	resolveMu.RLock()
	if cachedDir != "" && cachedFromCwd == cwd {
		cached := cachedDir
		resolveMu.RUnlock()
		return cached, nil
	}
	resolveMu.RUnlock()

	// The environment is deliberately inherited rather than scrubbed with
	// gitrepo.EnvWithoutRepoOverrides. The rule that exists for cmd.Dir/-C
	// subprocesses is about not silently operating on the hook's repo when the
	// caller meant a different one; here the hook's repo IS the target, so a
	// GIT_DIR git exported to us is the right answer, not contamination.
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
	cmd.Dir = "."
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get git common dir: %w", err)
	}

	dir, err := filepath.Abs(strings.TrimSpace(string(output)))
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}

	resolveMu.Lock()
	cachedDir = dir
	cachedFromCwd = cwd
	resolveMu.Unlock()

	return dir, nil
}

// ClearCache forgets the resolved path. Tests that change directory call it;
// production does not need to, because the cache is keyed by cwd.
func ClearCache() {
	resolveMu.Lock()
	cachedDir = ""
	cachedFromCwd = ""
	resolveMu.Unlock()
}

// Open returns the shared *os.Root over the git common directory. The returned
// root is owned by this package and shared with every other caller; do not
// close it.
func Open(ctx context.Context) (*os.Root, error) {
	dir, err := CommonDir(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAt(dir)
}

// OpenAt is Open for an explicit git directory — the common dir for callers that
// already resolved one or that act on another clone, and the per-worktree git
// dir for the few things that genuinely live there rather than in the common dir
// (the rebase/cherry-pick sequence markers).
func OpenAt(commonDir string) (*os.Root, error) {
	if commonDir == "" {
		return nil, errors.New("gitdir: common dir is required")
	}
	abs, err := filepath.Abs(commonDir)
	if err != nil {
		return nil, fmt.Errorf("resolve %s: %w", commonDir, err)
	}

	// osroot.Shared owns the open-at-most-once registry, shared with the other
	// anchors, and returns a missing directory unwrapped so callers can classify
	// it with os.IsNotExist — an ordinary outcome for a store asked about a repo
	// that has none.
	return osroot.Shared(abs) //nolint:wrapcheck // see comment
}

// Reset closes and forgets every cached root, and the resolved path with them.
// Call it after deleting or replacing a common dir: a root that outlives its
// directory is a handle to an unlinked inode, so writes through it succeed and
// land nowhere. The root registry is shared with the other anchors, so this
// clears those too.
func Reset() {
	osroot.ResetShared()
	ClearCache()
}

// CommonDirForWorktree returns the absolute git common directory for the
// repository at worktreeRoot, independent of the process's working directory.
//
// Callers acting on a repo passed as an argument (agent import, session adopt)
// must use this rather than CommonDir: the cwd-resolved form answers for
// whatever repo the process happens to be running in, which is how test
// fixtures once leaked session state into a developer's real
// .git/entire-sessions and hijacked commit linking.
//
// Not cached: the per-cwd cache CommonDir keeps would be wrong here, since the
// answer varies with the argument rather than with the process.
func CommonDirForWorktree(ctx context.Context, worktreeRoot string) (string, error) {
	// An empty root would silently degrade to the process cwd (cmd.Dir = ""),
	// reproducing exactly the accidental-repo leak this exists to prevent.
	if worktreeRoot == "" {
		return "", errors.New("gitdir: worktree root required to resolve a git common dir")
	}
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
	cmd.Dir = worktreeRoot
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("resolve git common dir for %s: %w", worktreeRoot, err)
	}
	// git answers relative to cmd.Dir, so this resolves against worktreeRoot and
	// never against the process's own directory.
	dir := strings.TrimSpace(string(output))
	if !filepath.IsAbs(dir) {
		dir = filepath.Join(worktreeRoot, dir)
	}
	return filepath.Clean(dir), nil
}

// OpenPathIn returns the shared root for commonDir together with absPath's name
// inside it, so a consumer holding an absolute path it was handed earlier can
// still read through the one root rather than through the path.
//
// It refuses a path that is not under commonDir instead of silently reading it.
// That refusal is only worth anything when commonDir is resolved INDEPENDENTLY
// of absPath: a caller that derives the base by walking up from the target makes
// the check vacuous, because the relative path is then correct by construction.
// settings.clonePreferencesRoot is the one caller, and it recovers the common
// dir by removing a compile-time constant suffix, which fails loudly on a path
// of the wrong shape rather than anchoring somewhere else.
//
// (The investigation stores used to be described here as callers. They are not:
// they hold a commonDir of their own and resolve run ids as names inside it,
// which is the stronger form — see investigate.StateStore.)
func OpenPathIn(commonDir, absPath string) (root *os.Root, name string, err error) {
	base, err := filepath.Abs(commonDir)
	if err != nil {
		return nil, "", fmt.Errorf("resolve %s: %w", commonDir, err)
	}
	target, err := filepath.Abs(absPath)
	if err != nil {
		return nil, "", fmt.Errorf("resolve %s: %w", absPath, err)
	}
	rel, err := filepath.Rel(base, target)
	if err != nil || rel == "." || paths.IsRelativeTraversal(rel) {
		return nil, "", fmt.Errorf("%q is not under %q", absPath, commonDir)
	}
	root, err = OpenAt(base)
	if err != nil {
		return nil, "", err
	}
	return root, filepath.ToSlash(rel), nil
}
package paths

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// GetWorktreeID returns the internal git worktree identifier for the given path.
// For the main worktree (where .git is a directory), returns empty string.
// For linked worktrees (where .git is a file), extracts the name from
// .git/worktrees/<name>/ path. This name is stable across `git worktree move`.
func GetWorktreeID(worktreePath string) (string, error) {
	gitPath := filepath.Join(worktreePath, ".git")

	info, err := os.Stat(gitPath)
	if err != nil {
		return "", fmt.Errorf("failed to stat .git: %w", err)
	}

	// Main worktree has .git as a directory
	if info.IsDir() {
		return "", nil
	}

	// Linked worktree has .git as a file with content: "gitdir: /path/to/.git/worktrees/<name>"
	content, err := os.ReadFile(gitPath) //nolint:gosec // gitPath is constructed from worktreePath + ".git"
	if err != nil {
		return "", fmt.Errorf("failed to read .git file: %w", err)
	}

	line := strings.TrimSpace(string(content))
	if !strings.HasPrefix(line, "gitdir: ") {
		return "", fmt.Errorf("invalid .git file format: %s", line)
	}

	gitdir := strings.TrimPrefix(line, "gitdir: ")
	if worktreeID, found := parseWorktreeID(gitdir); found {
		return worktreeID, nil
	}

	return "", fmt.Errorf("unexpected gitdir format (no worktrees): %s", gitdir)
}

func parseWorktreeID(gitdir string) (string, bool) {
	gitdir = strings.TrimSuffix(strings.ReplaceAll(gitdir, "\\", "/"), "/")

	// Submodule gitdirs live under .git/modules/<path>. If that submodule
	// repository has its own linked worktree, the gitdir ends with
	// .git/modules/<path>/worktrees/<id>. A /worktrees/ segment before the
	// final /modules/ belongs to the superproject's worktree, not the submodule.
	if modulesIndex := strings.LastIndex(gitdir, "/modules/"); modulesIndex >= 0 {
		afterModules := gitdir[modulesIndex+len("/modules/"):]
		if _, worktreeID, found := strings.Cut(afterModules, "/worktrees/"); found {
			return strings.TrimSuffix(worktreeID, "/"), true
		}
		return "", true
	}

	// Extract worktree name from path like /repo/.git/worktrees/<name>
	// or /repo/.bare/worktrees/<name> (bare repo + worktree layout).
	// The path after the marker is the worktree identifier.
