package gitrepo

import (
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

const windowsOS = "windows"

func TestResolveWorktreeMetadata_RealGitLayouts(t *testing.T) {
	t.Parallel()

	t.Run("ordinary repository", func(t *testing.T) {
		t.Parallel()
		root := filepath.Join(t.TempDir(), "ordinary")
